class BigNumCalculator:
    BASE = 10

    @staticmethod
    def _add_digits(num1, num2):
        max_length = max(len(num1), len(num2))
        num1 = num1.zfill(max_length)
        num2 = num2.zfill(max_length)

        carry = 0
        result = []
        for i in range(max_length - 1, -1, -1):
            digit_sum = int(num1[i]) + int(num2[i]) + carry
            carry = digit_sum // BigNumCalculator.BASE
            digit = digit_sum % BigNumCalculator.BASE
            result.insert(0, str(digit))

        if carry > 0:
            result.insert(0, str(carry))

        return ''.join(result)

    @staticmethod
    def _determine_sign(num1, num2):
        if len(num1) < len(num2):
            return num2, num1, True
        elif len(num1) > len(num2):
            return num1, num2, False
        else:
            if num1 < num2:
                return num2, num1, True
            else:
                return num1, num2, False

    @staticmethod
    def _subtract_digits(num1, num2):
        max_length = max(len(num1), len(num2))
        num1 = max_length and num1.zfill(max_length) or num1
        num2 = max_length and num2.zfill(max_length) or num2

        borrow = 0
        result = []
        for i in range(max_length - 1, -1, -1):
            digit_diff = int(num1[i]) - int(num2[i]) - borrow

            if digit_diff < 0:
                digit_diff += BigNumCalculator.BASE
                borrow = 1
            else:
                borrow = 0

            result.insert(0, str(digit_diff))

        while len(result) > 1 and result[0] == '0':
            result.pop(0)

        return ''.join(result)

    @staticmethod
    def add(num1, num2):
        return BigNumCalculator._add_digits(num1, num2)

    @staticmethod
    def subtract(num1, num2):
        num1, num2, negative = BigNumCalculator._determine_sign(num1, num2)
        result = BigNumCalculator._subtract_digits(num1, num2)
        if negative:
            result = '-' + result
        return result

    @staticmethod
    def multiply(num1, num2):
        len1, len2 = len(num1), len(num2)
        result = [0] * (len1 + len2)

        for i in range(len1 - 1, -1, -1):
            for j in range(len2 - 1, -1, -1):
                mul = int(num1[i]) * int(num2[j])
                p1, p2 = i + j, i + j + 1
                total = mul + result[p2]

                result[p1] += total // BigNumCalculator.BASE
                result[p2] = total % BigNumCalculator.BASE

        start = 0
        while start < len(result) - 1 and result[start] == 0:
            start += 1

        return ''.join(map(str, result[start:]))
